typedef struct Payload {
    long magic;
    int data;
} Payload;

// Side-effect-free content validation
int is_valid(const Payload* p) {
    // Reads, does not modify program state
    return p && (p->magic == 0xDEADBEEF);
}

void process_data(void* opaque_ptr) {
    Payload* p = (Payload*)opaque_ptr;

    // Complex Conditional Check (Null Check + Side-Effect-Free Validation)
    if (p && is_valid(p)) {
        // Guaranteed safe dereference
        p->data *= 2;
    }
}
